<script lang="ts">
 import type {Transaction} from '$lib/types';
 import {formatMoney,formatDate} from '$lib/utils';
 import Badge from './FinancialBadge.svelte';
 let {rows,expense=false,kind='unknown'}:{rows:{transaction:Transaction;contributionCents:number}[];expense?:boolean;kind?:'expense'|'income'|'transfer'|'unknown'}=$props();
 let query=$state(''),sort=$state('newest'),page=$state(1);
 const matching=$derived(rows.filter(r=>`${r.transaction.merchant??''} ${r.transaction.account_name??''}`.toLowerCase().includes(query.toLowerCase())).toSorted((a,b)=>sort==='amount'?Math.abs(b.contributionCents)-Math.abs(a.contributionCents):sort==='oldest'?a.transaction.date.localeCompare(b.transaction.date):b.transaction.date.localeCompare(a.transaction.date)));
 const pages=$derived(Math.max(1,Math.ceil(matching.length/25)));
 const visible=$derived(matching.slice((Math.min(page,pages)-1)*25,Math.min(page,pages)*25));
</script>
<div class="product-panel-body"><div class="product-toolbar" style:margin-bottom="0"><label class="product-field"><input type="search" aria-label="Search contributing transactions" placeholder="Search activity" bind:value={query} oninput={()=>page=1}/></label><label class="product-field"><span>Sort</span><select aria-label="Sort activity" bind:value={sort} onchange={()=>page=1}><option value="newest">Newest first</option><option value="oldest">Oldest first</option><option value="amount">Largest amount</option></select></label></div></div>
{#if visible.length}<div class="product-table-wrap"><table class="product-table"><thead><tr><th scope="col">Transaction</th><th scope="col" class="secondary">Account</th><th scope="col" class="amount">Included amount</th></tr></thead><tbody>{#each visible as r}<tr><td><a href={`/transactions/${r.transaction.id}`}>{r.transaction.merchant||'Transaction'}</a><span class="product-row-caption">{formatDate(r.transaction.date)}</span></td><td class="secondary"><a href={`/accounts/${r.transaction.account_id}?month=${r.transaction.date.slice(0,7)}`}>{r.transaction.account_name}</a></td><td class="amount"><Badge value={formatMoney(expense?-r.contributionCents:r.contributionCents)} label={expense?(r.contributionCents>0?'Refund':'Included spending'):kind==='income'?(r.contributionCents<0?'Income reversal':'Included income'):kind==='transfer'?'Movement':'Included amount'} tone={expense?(r.contributionCents>0?'positive':'neutral'):kind==='income'?(r.contributionCents<0?'negative':'positive'):kind==='transfer'?'movement':'neutral'}/>{#if r.contributionCents!==r.transaction.amount_cents}<span class="product-row-caption">Part of {formatMoney(Math.abs(r.transaction.amount_cents))}</span>{/if}</td></tr>{/each}</tbody></table></div><div class="product-panel-body" style:display="flex" style:justify-content="space-between" style:gap="12px"><span class="product-muted">{matching.length} {matching.length===1?'transaction':'transactions'}</span>{#if pages>1}<div style:display="flex" style:gap="8px"><button class="product-button" disabled={page<=1} onclick={()=>page--}>Previous</button><span class="product-muted" aria-live="polite">{Math.min(page,pages)} / {pages}</span><button class="product-button" disabled={page>=pages} onclick={()=>page++}>Next</button></div>{/if}</div>{:else}<div class="product-empty"><strong>{query?'No matching transactions':'No categorized activity in this view'}</strong><p>{query?'Try a different merchant or account.':'Choose another month, or review activity that still needs a category.'}</p><a class="product-link" href="/transactions">Review activity</a></div>{/if}
